INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, test_String) SELECT @e, 65, 0, 0, 1, 'AzimarWeapon' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, test_String) SELECT @e, 66, 0, 0, 0, 'AzimarLines:weapon' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, test_String) SELECT @e, 67, 8, 1.0, 0, 'Go gently, %s. The winds are with you.', 'AzimarLines:bless' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, test_String) SELECT @e, 0, 8, 0, 0, 'The winds are kind today.', 'AzimarLines:idle' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Well, well, well. Hello, %s. I am Azimar, and I have just decided you are my type.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! Fresh off the portal, unbuffed, and standing right in my breeze. Lucky, lucky me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Oh, a new one. Hello, %s. Do not be shy. I am shy enough for both of us. I am lying.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Welcome, %s. First time with a Zefir? Relax. Breathe. Let the professional handle it.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, '%s, darling. Where have you been all my life? Probably on the Holtburg road. Tragic.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Hello, %s. I am Azimar the Gleaming. Gleaming noticeably harder now that you are here.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'Brand new and already making my wings flutter, %s. Scandalous. Do it again.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Step into my breeze, %s. Everyone leaves glowing and slightly flustered. Mostly flustered.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 8, 8, 0, 0, 'Hello, %s. I am Azimar. You may call me Azimar. Or anything, really. I am not fussy.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 9, 8, 0, 0, 'Oh, %s, you walked right into my breeze. Where I come from, that is basically a proposal.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 10, 8, 0, 0, 'A new arrival! %s, you are going to love it here. I am personally going to make sure of it.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 11, 8, 0, 0, '%s! Fresh face, fresh start, and the best-looking Zefir in Dereth to greet you. Lucky.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 12, 8, 0, 0, 'Welcome to Dereth, %s. The monsters bite. I only flirt. Choose wisely.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 13, 8, 0, 0, 'Well hello, %s. Do not mind the sparkling. It only happens when I am interested.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 14, 8, 0, 0, '%s, is it? Lovely name. I will be saying it a lot. Get used to that.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 15, 8, 0, 0, 'New in town, %s? I give the warmest welcome in Dereth. Ask anyone. Watch them blush.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s! Back so soon? Admit it. You came for the buffs and stayed for me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'There you are, %s. I was starting to think you only loved me for my magic.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Ah, %s, my favourite regular. The usual? Every buff I have and some very heavy flirting?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%s returns! Somebody hold me back. No, wait. You hold me back. Closer.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Welcome back, %s. I have been hovering here thinking about you. Hovering suggestively.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%s! My wings went all a-flutter the moment you walked in. Again. Every time.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, '%s! You came back. They always come back.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Look who could not resist. Hello again, %s.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 8, 8, 0, 0, '%s, my darling regular. I kept your spot in my breeze nice and warm.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 9, 8, 0, 0, 'Oh good, %s is here. My day just got noticeably more interesting.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 10, 8, 0, 0, 'Back for seconds, %s? I do admire a healthy appetite.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 11, 8, 0, 0, '%s again! People will think you only come here to see me. They would be right.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s! Days without a word? I nearly blessed a mosswart out of sheer loneliness.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Look who the storm blew back. %s, I wrote you poems while you were gone. Mostly sighing.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, '%s! Where have you been? No, do not tell me. Just stand there and let me look at you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Days, %s! A Zefir has needs. Mainly you. Also gossip. But mainly you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, '%s! You left me hovering alone for days. Do you know how dull drudges are to talk to?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Oh, now you remember me, %s. Hmph. Fine. Come here. I forgive you instantly.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, '%s, back at last! I nearly flew off to find you. Then I got comfortable again.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Days, %s. Days! I counted every single gust. Welcome home.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Your %visit visit, %s! All of Dereth is talking about us. Let them talk.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s, that is %visit times now. At this point we should tell your patron.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'The %visit visit, %s. I keep count. I also keep a little shrine. Joking. Mostly.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%s, your %visit time! I am naming a breeze after you. It is a very warm one.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Visit number %visit, %s. If this is not love, it is at least a very good habit.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%s, this makes %visit. I am running out of ways to act surprised. Still thrilled.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'The %visit time, %s! At this rate I should get you a key to my cloud.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'This is your %visit visit, %s. Your patron must be so jealous.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Fresh on the road, %s? I love a project. Let me take you under my wing. Literally.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Never mind your level, %s. To me you are already a legend. A very cute one.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Mind the drudges, %s. Nobody ruffles your feathers but me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Still new to the road, %s? Do not worry. I am patient. Extremely patient. Mostly.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Just starting out, %s? Everyone remembers their first Zefir. Make it me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'A word of advice, %s: buffs first, heroics second, me always.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'My, my, %s. Somebody has been out slaying things. It shows. I am not complaining.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Look at you, %s, all grown up and dangerous. Stop it. No, keep going.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Halfway up the mountain, %s? Catch my tailwind, gorgeous. I can take you higher.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%s, you have grown stronger. I can tell. Something about the way you walk in now.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Ooh, %s. Tougher every visit. I am not saying it is working on me. It is working on me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Look at you, %s. The olthoi had better watch out. So had I.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s, you seasoned devil. Experience looks so good on you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Your name blows in on every breeze, %s. I always leave the window open.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'A veteran! Welcome, %s. Tell me about every fight. Slowly. With details.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%s, so seasoned, so capable. Do you ever take a day off? Perhaps with me?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Ah, %s. All those battles and you still found time for me. I am honoured. And flustered.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'A true veteran, %s. You make it all look easy. Show-off. Do it again.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%s! An actual legend, in my breeze. Somebody fan me. Oh wait. I am the fan.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'The high winds bow to you, %s. I would too, but then I could not gaze at you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'So much power, %s. So much glory. So very close to me. I may need a moment.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%s! I heard the ground shake. Oh. That was just my heart.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, '%s, a living legend. I am not worthy. I am, however, available.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Bow before %s, everyone. Then step aside. I want the best view.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Good morning, %s. I woke up thinking about you. Then I woke up properly. Still you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Up with the sun, %s? So am I. Wide awake. Fully hovering. Ready for anything.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Morning, %s. Breakfast? I am serving warm winds and terrible intentions.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Good morning, %s. I made you breakfast. It is a breeze. I only make breezes.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Morning, %s. You look radiant. I look radiant. We should be radiant together.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Early start, %s? I like a go-getter. Go get buffs. From me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Good afternoon, %s. My schedule is wide open, and so are my wings.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Hot day, %s. I could cool you down with a breeze. Or make it much worse. Your call.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Hello, %s. The midday sun is shining on you, and frankly it is showing off.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Afternoon, %s. Sun is out, wings are out. Shall we?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Good day, %s. I was terribly bored until about two seconds ago.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Midday, %s, and you are the brightest thing in the sky. Besides me. Barely.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Good evening, %s. Soft light, warm winds, just the two of us. Ignore the drudges.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Sunset, %s. The most romantic hour in Dereth. For buffing. Purely buffing. Sure.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Evening, %s. The sky turns gold to match me. Do you like it? Do you like me?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Good evening, %s. Shall we dim the lights? I cannot. I am gleaming. Sorry.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Evening, %s. Dinner? Drinks? Every buff I have? I know which one you want. Do you?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'The day is done, %s, and the night is young. Much like my intentions.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Out late, %s? The night winds keep secrets. I have ideas for a few new ones.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'A midnight visit, %s? Scandalous. I will tell no one. I will tell everyone.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Cannot sleep, %s? Me neither. Whatever shall we do? Buffs. We shall do buffs.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Late night, %s? I glow in the dark. Very handy. Very romantic.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, '%s, at this hour? Everyone else is asleep. It is just us. And a few undead.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'The moon is up, %s. So is my interest. Come closer.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, '%n spreads his shimmering wings. "Hold still, gorgeous. This might tickle."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%n spreads his wings wide and winks. "Eyes up here, darling. The magic happens up here."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, '%n spreads his golden wings. "Closer. Closer. Perfect. For the magic, of course."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, '%n spreads his wings and hums something low and sultry. A Zefir love song, probably.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, '%n spreads his wings, scattering sparkles. "Brace yourself. I am very, very thorough."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%n spreads his shimmering wings. "Ready? I never do anything halfway."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, '%n spreads his wings slowly. Very slowly. "Enjoying the show? I know I am."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, '%n spreads his wings and leans in. "Say ahh. No, wait, that is the healer."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 8, 8, 0, 0, '%n spreads his golden wings with a flourish. "Ta-da. Now hold still, gorgeous."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 9, 8, 0, 0, '%n spreads his wings and winks twice. "Once for luck. Once for you."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 10, 8, 0, 0, '%n spreads his wings, glowing brighter. "Ignore the shimmer. It means I like you."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 11, 8, 0, 0, '%n spreads his wings around you. "Cozy, isn''t it? Now, the magic."' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'There. Was it good for you too, %s? It was wonderful for me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'All done, %s. You are positively glowing. People will know where you have been.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Go on, %s. Think of me when the glow fades. Think of me a little before, too.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'That should last a while, %s. My longing for you will last much longer.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Blessed, buffed and breathtaking. Come back for more, %s. Everyone comes back.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Off you go, %s. Break a few hearts out there. Save mine for last.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'Fly well, %s. I would wave, but I am busy watching you leave. Very closely.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Safe winds, %s. If anyone asks where you got that glow, just wink and say Azimar.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 8, 8, 0, 0, 'Finished, %s. You may go. You will not want to, but you may.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 9, 8, 0, 0, 'Buffed to perfection, %s. You are welcome. Come back and thank me properly.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 10, 8, 0, 0, 'Done, %s. Now go out there and be gorgeous at something dangerous.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 11, 8, 0, 0, 'All yours, %s. Every buff, and a little piece of my heart.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 12, 8, 0, 0, 'Glowing again, %s. People will start to talk. Let them.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 13, 8, 0, 0, 'Off with you, %s. Shoo. Come back soon. Not that soon. Actually, that soon.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 14, 8, 0, 0, 'That was lovely, %s. Same time tomorrow? Same time in thirty seconds?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 15, 8, 0, 0, 'Go, %s. Whatever bites you out there will not be half as charming as me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Your first time, %s, and you were wonderful. I will never forget it. Come back.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Remember the name, %s: Azimar. Shout it at your enemies. Whisper it to me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'That glow is mine now, %s. When it fades, you know whose wings to come crawling back to.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'You will remember your first blessing forever, %s. I certainly will.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'There. Now you are officially one of mine, %s. Welcome to the family.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'First one is free, %s. So is every one after. I am terribly generous.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Your weapon blessings are on you, %s. They wake the moment you wield a weapon or wand.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Empty hands, %s? Tempting. Pick up a blade, a bow or a wand and my blessing is already in it.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'I blessed your grip, %s, not a weapon. Hold anything you like. It will feel me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Nothing in your hands, %s? My blessing waits for any weapon or wand you pick up. So do I.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Your weapon blessings are on you, %s, waiting. Wield something and they leap right in.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'No weapon, %s? Bold. My blessing is on you anyway, ready for the first blade or wand you hold.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'That weapon of yours will not take my magic, %s. Playing hard to get. I respect it.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Your weapon rejects me, %s. Rude. Wield another and my blessing goes straight to it.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Your weapon will not let me in, %s. Some blades are shy. Wield another and I am in it.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'That one refuses enchantment, %s. I am not offended. Mostly. Wield another for my blessing.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Patience, %s. Even I need a moment between rounds. Come back in %tqt.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'So eager! I adore that in a person. Give me %tqt to recover.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Again already, %s? Insatiable. Flattering. Try me in %tqt.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Easy, %s. Anticipation is half the fun. The other half starts in %tqt.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Not yet, %s. A Zefir needs time to recharge his sparkle. Come back in %tqt.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Ooh, demanding. I like it. Come back in %tqt, %s.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'Still glowing from last time, %s? Me too. %tqt more.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Breathe, %s. Admire me from over there. %tqt to go.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'The winds are restless today. Or that is just me, thinking about all of you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Psst, %s. Yes, you. Looking for a good time? I have buffs. And no shame at all.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'I could ruffle more than your feathers, you know. With magic. Mostly magic.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Do not mind me. Just hovering here. Looking magnificent. Available.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Free blessings! Warm winds! Satisfaction guaranteed or your glow back!' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%s, you look like someone who needs a lift. I give excellent lifts.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'My kin chase storms. I chase adventurers. I am faster than I look.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Is it warm in here, or is that just everyone standing near me?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 8, 8, 0, 0, 'Blessings here! Fresh, warm, and given with far too much enthusiasm!' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 9, 8, 0, 0, 'Anyone need a buff? A compliment? A long, lingering look? All free.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 10, 8, 0, 0, 'I have been told I am too much. I have decided that is a compliment.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 11, 8, 0, 0, '%s, you walked past without saying hello. I will survive. Barely.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 12, 8, 0, 0, 'If you are looking for trouble, I am right here. Glowing. Obviously.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 13, 8, 0, 0, 'Some say Zefirs are wild and dangerous. Only the fun ones.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 14, 8, 0, 0, 'Come closer, adventurers. I do not bite. The drudges do.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 15, 8, 0, 0, 'Hovering, hovering, hovering. Waiting for someone to notice me. Hint.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Ahh, a fresh morning breeze. Right through the feathers. Delicious.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Rise and shine, %s. Come let me put some wind in your sails. First thing.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Another lovely morning in Dereth. Someone come and make it lovelier.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Morning, %s. Nothing wakes you up like a Zefir. Try me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'The stars are out. Perfect light for a little mischief. Who is in?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Up late, %s? Me too. Funny how we keep finding each other in the dark.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Night falls. My favourite time for bad decisions. Like blessing everyone twice.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'The moon is out, %s. Shall we gaze at it? You may gaze at me instead.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Happy Frostfell, %s! Come under my wing. Warmest spot in Dereth, and it is all yours.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! Freezing out there. Lucky for you, I run very, very hot.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Frostfell greetings, %s. Like the hat? Be honest. No, be flattering. Very flattering.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Snow on the ground and you at my side, %s. Who needs presents?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Frostfell, %s! I will be your hearth tonight. Gather round. Closer. Closer.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Merry Frostfell, %s. I got you something. It is me. Again.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, '%s! Snowflakes in your hair. Adorable. Let me blow them away. Gently.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Cold hands, %s? Warm winds right here. No charge. A hug, maybe.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Presents hidden all over town, and the best one is hovering right here. No wrapping.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Brr. Someone come stand close. For warmth. Purely for warmth. Closer than that.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Frostfell is the season of giving. I am mostly giving looks.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Snow everywhere, and still I am the hottest thing in town.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Spring is here, %s, and so are you. Everything is blooming. Especially me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! Smell the flowers? The wind picked them for you. I am the wind.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Happy Spring Festival, %s. Birds and bees everywhere. Do not look at me like that.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'The eggs are hidden and you found me instead, %s. Best prize in the hunt.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Spring has sprung, %s, and so have I. Right toward you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%s! The birds are singing. I would sing too, but it would be about you. Awkward.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'Happy spring, %s. Everything is fresh and fluttering. Especially my wings.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Spring fever, %s? I have had it for weeks. Blame the flowers.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Flowers in my crown and a spring in my wingbeat. Somebody come and notice.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Spring air does wonders for the feathers. Feel free to stare.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Fresh blossoms, warm breezes, and me. Spring really has everything.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Something about spring makes a Zefir want to flutter at strangers.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Welcome, %s. Do I look the part? I always dress up for a wedding. Just in case.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! The royal couple are celebrating, and frankly, so could we.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'A wedding, a top hat, and you, %s. I am hovering on one knee. Just saying.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Love is in the air, %s. Mostly it is me, but you are welcome to breathe it in.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, '%s! Weddings make everyone romantic. More romantic than me? No. Never.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'Here for the wedding, %s? Lovely. Shall we start some rumours of our own?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, '%s, you clean up nicely. Wedding season suits you. So would I.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Welcome, %s. The cake is gone, but the best dessert is hovering right here.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Weddings make me sentimental. Someone come be blessed before I propose to a lamppost.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'I caught the bouquet. Nobody threw it. I just took it. Now, who wants it?' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Somebody is getting married. It should have been me. To all of you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Love and blessings, free at this booth. Mostly love.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Another year of Dereth, %s! Watch the sky. Or watch me. I am the better show.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! The fireworks are out and so is my good side. It is every side.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Happy Anniversary, %s. I sparkle on special days. Today I am sparkling at you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Fireworks above and you right here, %s. My heart is going boom.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Another year, %s, and you only get better. Like me. But less shiny.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, '%s! Anniversary sparkle! Mine is brighter, but yours is lovely too.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, 'Cheers to another year of Dereth, %s, and another year of me admiring you.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'Happy Anniversary, %s. You get a blessing. I get a good look at you. We both win.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Ooh, fireworks. Pretty. Not as pretty as the crowd near me, though.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'Another year of adventurers, each more charming than the last. This job is lovely torture.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Every year more adventurers, and every year I flirt with all of them. Tradition.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'Fireworks overhead. Sparks down here. Coincidence? I think not.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'Happy New Year, %s! My resolution: flirt more. Off to a strong start.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, '%s! New year, fresh start, same irresistible Zefir.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'To the new year, %s. May your packs be full, your vitae empty, and your evenings mine.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'New Year greetings, %s. I saved my first blessing of the year for you. And my second.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 4, 8, 0, 0, 'Happy New Year, %s! A midnight kiss? No? A blessing, then. Fine.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 5, 8, 0, 0, 'New year, %s, and I have resolved to be even less subtle. Watch me.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 6, 8, 0, 0, '%s! A whole new year to visit me. Do not waste a single day.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 7, 8, 0, 0, 'To you, %s, and to every bad decision we make this year. Mostly buffs.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 0, 8, 0, 0, 'A toast to the new year. And to anyone brave enough to stand next to me at midnight.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 1, 8, 0, 0, 'New year, new wings. Same old shameless charm. Come see.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 2, 8, 0, 0, 'Midnight came and nobody kissed me. I am blessing out of spite now.' FROM DUAL WHERE @e IS NOT NULL;
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT @e, 3, 8, 0, 0, 'New year, same Zefir. Still gorgeous. Still single. Still hovering.' FROM DUAL WHERE @e IS NOT NULL;
